from pathlib import Path
import csv,datetime,json,re,subprocess,fitz
b=Path(__file__).resolve().parent.parent;w=b/'work';d=b/'deliverable'
now=datetime.datetime.now(datetime.timezone.utc)
cut=datetime.datetime(2026,11,21,5,2,4,tzinfo=datetime.timezone.utc)
if now<cut:raise SystemExit('Formal six-hour review cannot be finalized before its scheduled cutoff.')
subprocess.run(['python3',str(w/'merge_audits.py')],check=True)
qs=list(csv.DictReader((d/'QUESTIONS.tsv').open(),delimiter='\t'));checks=list(csv.DictReader((d/'CHECK_EVENTS.tsv').open(),delimiter='\t'))
pages=len(fitz.open(d/'ALPOGE_GCT.pdf'))
s=(w/'review_06h_intro_draft.md').read_text()
s=s.replace('The completion timestamp and register counts are inserted when this review is finalized.',f'Actual review completion: {now.isoformat()}. The register contains {len(checks)} check events and {len(qs)} question rows; the current compiled paper has {pages} pages.')
s=s.replace("The snapshot's exact build and audit counts are inserted below when this review is finalized.",f'The current build has {pages} pages and {(d/"ALPOGE_GCT.pdf").stat().st_size:,} bytes. Three TeX passes succeeded with no overfull boxes, undefined references or rerun warning. All newly integrated proof pages and revised status pages were visually inspected in contact sheets42–48; prior body portions retain their earlier checks. There are {len(checks)} check events and {len(qs)} question rows.')
rows=[q for q in qs if q.get('current_gate','').strip() or re.search(r'open|partial|gate|unresolved|unchecked|not settled|undecided',q['state'],re.I)]
s+=f'\n## Complete conservative open-or-partial inventory ({len(rows)} rows)\n\nRows with a proved core and an explicit remaining comparison are retained. A historical auxiliary estimate is not counted as an unresolved main index question where P57 has already settled that question.\n'
for q in rows:
 s+=f"\n### {q['id']}\n\nSource and locator: {q['source_and_locator']}\n\nQuestion: {q['question']}\n\nRecorded state: {q['state']}\n\nFindings or counterexample: {q['finding_ids_or_counterexample']}\n\nCurrent gate: {q['current_gate'] or 'No additional gate recorded; see the precise scope in the state.'}\n"
s+='\n## Work before the next review\n\nCompute the second tensor component stabilizer and fixed tangent, then seek an actual comparison of all global Hilbert contributions. Test source-compatible finer categorical/trace dictionaries after the integral Euler obstruction. Investigate a population-preserving amplification for narrow ordinary plethysm, and the exact supplied theta-operation comparison. These are active main-gate attempts. No movement will be credited merely for more fixed examples or repackaging. Next formal review:06:02:04UTC. Next checkpoint:05:47:04UTC.\n'
(d/'FORMAL_REVIEW_06H.md').write_text(s)
with (d/'LEDGER.md').open('a') as f:f.write(f'\n## Formal six-hour review — {now.isoformat()}\n\nScheduled cutoff05:02:04UTC. Movement:YES; consecutive scheduled reviews without qualifying movement:0; continue. P57 closes the preexisting strict-index gate, P60 closes the actual Kronecker canonical-parameter clause, and P52 narrows the source category comparison to canonical coefficient objects/mixed coherence. P63 closes the broad density clause under its explicit finite additive coding convention; P64 refutes the single-component shortcut. The review contains every conservative open/partial row ({len(rows)}) with its state and gate. Current paper:{pages}pages; checks:{len(checks)}; questions:{len(qs)}. Next review06:02:04UTC; next checkpoint after08 is05:47:04UTC.\n')
p=d/'README.md';t=p.read_text().replace('and FORMAL_REVIEW_05H.md.','FORMAL_REVIEW_05H.md and FORMAL_REVIEW_06H.md.');t=t.replace('The five-hour review found qualifying movement and reset the consecutive stagnation count to zero. The next scheduled review is05:02:04UTC; the next checkpoint is05:02:04UTC.', 'The six-hour review found qualifying movement and reset the consecutive stagnation count to zero. The next scheduled review is06:02:04UTC; the next checkpoint after08 is05:47:04UTC.');p.write_text(t)
(w/'review_state.json').write_text(json.dumps({'last_scheduled_utc':cut.isoformat(),'completed_utc':now.isoformat(),'movement':True,'consecutive_stagnation':0,'next_review_utc':'2026-11-21T06:02:04+00:00','next_checkpoint_utc':'2026-11-21T05:47:04+00:00','checks':len(checks),'questions':len(qs),'open_partial_inventory':len(rows)},indent=2))
print({'review_completed':now.isoformat(),'movement':True,'stagnation':0,'checks':len(checks),'questions':len(qs),'inventory':len(rows),'pages':pages})
